WITH base AS (SELECT id, product_name, category, brand, price, cost, launch_date, tags, CAST(price AS INT) AS price_int, COALESCE(brand, 'UNKNOWN') AS brand_clean FROM products WHERE brand IS DISTINCT FROM 'Globex' AND brand IN ('Umbrella', 'Stark')), enriched AS (SELECT *, LAST_VALUE(price) IGNORE NULLS OVER (PARTITION BY brand ORDER BY price_int, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_price, LAST_VALUE(brand) IGNORE NULLS OVER (PARTITION BY category, brand ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_brand, ROW_NUMBER() OVER w_ordered AS event_seq, CORR(cost, price) OVER (PARTITION BY brand) AS corr_cost_price FROM base WINDOW w_ordered AS (ORDER BY price_int, id)), valid AS (SELECT *, cost / NULLIF(corr_cost_price, 0) AS cost_per_corr_cost_price, COALESCE(brand, 'OTHER') AS brand_filled FROM enriched WHERE launch_date > DATE '2023-09-03' AND brand IS NOT NULL), not_flagged AS (SELECT s.* FROM valid s WHERE EXISTS (SELECT 1 FROM store_sales x WHERE x.product_id = s.id AND x.sale_date BETWEEN '2024-01-01' AND '2024-10-01')) SELECT brand, COUNT(*) AS row_count, SIZE(COLLECT_SET(brand)) AS num_brands, ROUND(AVG(cost_per_corr_cost_price), 2) AS avg_cost_per_corr_cost_price, GROUPING(brand) AS grouping_id FROM not_flagged GROUP BY CUBE (brand) HAVING ROUND(AVG(cost_per_corr_cost_price), 2) > 0 ORDER BY brand DESC;
